import { OWNER_SUPPLIED, type EventTable } from "./types";

/** Таблица из документа, переданного владельцем. Строки описательные: движок бросает
 *  и показывает выпавшее, применяют его за столом. */
export const TABLES: readonly EventTable[] = [
  {
    id: "random-events",
    name: "Случайные события",
    group: "Странности и последствия",
    die: 100,
    source: OWNER_SUPPLIED,
    rows: [
      { from: 1, to: 1, text: "Под вашими ногами оказывается банановая кожура / тыквенная корка / гололёд. Сделайте проверку Внимательности (Сл 16), чтобы избежать падения. Если избежать падения не удалось, из лежачего положения вы замечаете любопытную вывеску или другой занимательный объект. Кстати, ощутимо приложившись головой: получите 1к4 урона." },
      { from: 2, to: 2, text: "Во время форсирования моста могучая лапа хватает вашего персонажа и утаскивает под мост. Сделайте спасбросок Телосложения (Сл 18). В случае неудачи получите 1к4 урона от удара о мост. Под мостом сидит огромный тролль, который в крайне агрессивной форме интересуется, уважаете ли вы его. Совершите спасбросок Мудрости или Харизмы (Сл 18). В случае неудачи начинается боевое столкновение. В случае успеха, тролль отпускает вас и, пуская слезу, сокрушается, что на всём свете только вы его уважаете. Он предлагает распить с ним бочонок сивухи. В процессе диалога можно выяснить, что этот тролль - изгой своего племени, поскольку имел постыдную склонность к созиданию (хаотично-нейтральное мировоззрение). В частности, занимается возведение мостов..." },
      { from: 3, to: 3, text: "Посреди дороги вы находите необычный трофей - это кроличья лапка на ярко-зелёном шнурке с крупной бусиной из лунного камня. Если вы подбираете его, все ваши проверки, атаки и броски в ближайшие сутки будут проходить с преимуществом. Однако, стоит вам передать, продать или потерять его - все ваши проверки, атаки и броски будут совершаться с помехой в ближайшие сутки. Если вы захотите оставить трофей себе, спустя сутки вы всё равно обнаружите его пропажу." },
      { from: 4, to: 4, text: "Совершите проверку Восприятия. В случае успеха вы замечаете, как некто опустошает свой ночной горшок из окна прямо над вами, и вас задевают лишь брызги. В случае провала ОНО с плеском льётся вам на макушку, забрызгивая в том числе сопартийцев. Зловоние и испорченный внешний вид сильно усложняют любое социальное взаимодействие партии в течение суток либо до тех пор, пока они не смогут отмыться и очистить одежду." },
      { from: 5, to: 5, text: "У дороги плачет маленькая девочка. Завидев вас, она растирает слёзы ладошками по лицу и просит вас помочь: \"большая птичка\" утащила её лукошко с цветами, а она зарабатывает продажей цветов. Если вы отказываетесь, ваша репутация в поселении снижается, поскольку все знают эту сироту. Если вы соглашаетесь, она ведёт вас к поляне, где она последний раз видела \"большую птичку\": там вас ждёт совомедведь." },
      { from: 6, to: 6, text: "Во время передвижения верхом овод или шершень больно ужалил вашу лошадь в круп, отчего та неожиданно взбрыкивает. Совершите проверку Ловкости с помехой (Сл 18), чтобы удержаться в седле! В случае неудачи получите 2к4 урона от падения. С вами или без, лошадь уносится вперёд. Однако, одним единственным жестом её останавливает странного диковатого вида старушка..." },
      { from: 7, to: 7, text: "Двигаясь в толпе, совершите проверку Внимательности с помехой (Сл 18). В случае успеха, вы успеваете заметить, как какой-то вор пытается умыкнуть ваше оружие / фокусировку, и можете погнаться за ним. В случае неудачи, через некоторое время вы встретите уличного зазывалу, который приглашает вас в открытую лавку разностей поблизости. Что это лежит на прилавке? Неужели! Торговец ни в какую не отдаст вам украденную вещь, настаивая, что она честно приобретена им в других землях, а пара крупных стражников, ошивающихся рядом, подтверждает авторитетность этого утверждения. Нет сомнений, что и эти стражники, и лавочник связаны с местной воровской кодлой..." },
      { from: 8, to: 8, text: "Совершите проверку Восприятия (Сл 18). В случае неудачи, прямо с неба на вас падает человек, нанося 2к4 урона. При осмотре вы можете понять, что он не дышит вследствие остановки сердца без видимых причин. На его ногах надеты очень подозрительного вида башмаки..." },
      { from: 9, to: 9, text: "Откуда ни возьмись на вас нападает целый пчелиный рой! Сделайте бросок 1к20 - столько укусов вам придётся пережить. Каждые два укуса наносят 1 урона. Плюс получите 1 продолжительного урона ядом. Перебив пчёл магией или убежав, вы обнаруживаете на себе причину злоключений - их матку..." },
      { from: 10, to: 10, text: "Прямо у вас под ногами внезапно открывается арка портала, откуда с криком выбегает некий маг в опалённой робе и скрывается в неизвестном направлении. Вы же проваливаетесь внутрь, оказываясь в самой гуще абордажной рубки. Плюсы: портал остался открытым, и вы можете вернуться. Минусы: корабль медленно, но верно движется, и точка пространства, в которой создана арка портала, понемногу движется за борт, а команды кораблей ожесточены сражением и рубят всякого чужака..." },
      { from: 11, to: 11, text: "Под вашими ногами оказывается куча навоза, незаметная в траве / уличной грязи. Сделайте проверку Внимательности (Сл 16) с помехой, чтобы избежать казуса. Если избежать этого шага не удалось, ваши проверки Убеждения до конца дня будут проходить с помехой. Однако, внутри оказывается небольшой ценный предмет: крупный жемчуг или самоцвет. Чей это скот тут проходил?" },
      { from: 12, to: 12, text: "Совершите спасбросок Ловкости (Сл 18). В случае неудачи вам в глаз влетает какой-то жучок и больно кусает вас в глаз. Место укуса тут же начинает нарывать, раздражая и принося неудобства. Все проверки навыков и атак будут проходить с помехой, пока вы не излечите хотя бы 1 hp. К слову о жуке: присмотревшись, вы замечаете, что это не обычный жук, а механизм!" },
      { from: 13, to: 13, text: "В момент следующего взаимодействия с магической сущностью (плетение заклинания, принятие на себя союзного или вражеского заклинания, использование магического предмета, в том числе ношения предметов с перманентным эффектом) вы случайно оказываетесь в точке крошечного узла дикой магии. Как следствие, вместо ожидаемого эффекта происходит оглушительный хлопок, отбрасывающий вас назад на 10 футов и оглушающий на один ход. Придя в себя и поднявшись, вы с удивлением понимаете, что ваш язык онемел. Эффект немоты сохраняется в течение трёх суток, во время которых вы можете объясняться исключительно с помощью жестов (можно попросить игрока непосредственно отыгрывать этот процесс). Вскоре вы обнаруживаете, что понимаете абсолютно любой язык, даже если раньше его не знали и не слышали (относятся ли к таковым языки животных и растений - решает мастер). Эффект сохраняется трое суток." },
      { from: 14, to: 14, text: "По непонятным причинам у вас начинает чесаться лоб с левой или с правой стороны. Вскоре в этом месте нарастает небольшая, но заметная шишка. После каждого следующего продолжительного отдыха сделайте спасбросок Телосложения. В случае провала вы обнаруживаете, что за время отдыха шишка подросла и потвердела, напоминая... молодой рог! Если вы пробуете молиться, разговаривать со служителями храмов или находится на территории святых мест, относящихся не к хаотичным и не к злым божествам, сделайте спасбросок Телосложения. При неудаче вам становится дурно вплоть до потери сознания. Во время отдыха вам начинают снится сны, полные тёмного огня. При провале спасброска после следующего продолжительного отдыха, вы обнаружите полноценный рог величиной в три дюйма. Вы понимаете, что не можете войти в святые места, а серебро и освящённое оружие наносит вам дополнительный урон излучением 1к4. Зато у вас появилось сопротивление огню и умение понимать на слух язык Бездны! Теперь после каждого продолжительного отдыха делайте спасбросок Мудрости. Как только вас настигнет неудача в этой проверке, вы услышите голос, который будет разговаривать с вами внутри вашей головы. Оказывается, все ваши злоключения - следствие попытки неопытного и слабого демона занять ваше тело." },
      { from: 15, to: 15, text: "Совершите проверку Восприятия (Сл 18). При неудаче вам в затылок прилетает обломок подковы, нанося вам 1к4 урона. Осмотревшись, вы можете обнаружить прохожего, говорящего под нос что-то про то, что найти обломок подковы - плохая примета, и что хорошо, что он быстро бросил её наотмашь через левое плечо..." },
      { from: 16, to: 16, text: "После очередного привала, вас начинают преследовать мелкие неудачи. Сапоги вдруг обзавелись дырками, со стрелы куда-то делось всё оперение, важное место в книге оказалось залито чернилами, вместо табака в кисете оказалась палая листва, ремешок перевязи для вашего оружия оказался подточен, порвавшись и упав в самый нужный момент, а на вашу лежанку вдруг пришли муравьи, хотя вы проверяли место на наличие муравейников... Причиной тому преследующее вас мелкое мстительное существо: фея, спригган или домовой. Оказалось, что на привале вы случайно разрушили его жилище или как-то ещё ненароком испортили ему жизнь." },
      { from: 17, to: 17, text: "Заходя за угол в неком переулке, вы слышите восклик \"Попался, гадёныш!\" Совершите спасбросок Ловкости (Сл 18). В случае неудачи незнакомец бьёт вас по лицу дубиной: получите 1к6+4 урона и состояние Ошеломлённый. В случае удачи вам удаётся увернуться, и удар лишь скользнул по вам - получите половину урона. Если вы были один и по вам прошёл полный урон, вы просто слышите \"...опять не он!..\" и, поднявшись, никого рядом не обнаруживаете. Если же вы устояли или с вами вместе был кто-то ещё, то обнаруживаете на месте здоровяка, который оправдывается, что подстерегал на этом месте своего знакомого. Дабы замять ситуацию с дубиной и переулком, он предлагает пару серебряных монет." },
      { from: 18, to: 18, text: "На улице к вам подбегает незнакомец в капюшоне. Быстро бросив вам \"Нет времени объяснять! Держи!\", он всучил вам в руки какую-то резную деревянную шкатулку весом 1к4 фунтов и бежит дальше. Вы успеваете понять, что шкатулка не открывается (к слову, на ней вообще не видно замка, а попытки сломать её оружием или магией ни к чему не приведут) и что внутри приятно стучат и позвякивают мелкие предметы, как из того же переулка выбегает полурослик с крайне миловидным лицом в вычурном одеянии. \"Ах вот ты где! Немедленно верни её мне!\" Говорит он. Если вы отказываетесь, он щёлкает пальцами. Позади него как по волшебству обнаруживаются (сколько весила шкатулка?) +1 драконорождённый-солдат. Полурослик командует \"Заберите у него моё добро, ребята, и сломайте ему руки!\" К слову, если вы соглашаетесь, он просто просит их намять вам бока. Чем бы эта история ни закончилась, позднее вас снова встретит незнакомец, всучивший шкатулку и, в случае возврата, предложит-таки выкрасть её вместе, а в случае вашей победы над наёмниками - скажет, что знает, как её открыть, и, если вы отдадите ему саму шкатулку, он согласен отдать вам содержимое." },
      { from: 19, to: 19, text: "На улице некто в кандалах указывает на вас пальцем страже, и те окружают вас. Этот человек осуждён на смерть за покушение на убийство высокого сановника, выходца из простых, но у него был подельник / заказчик. После пыток он, де, сознался, где обычно обретается его дружок, и вот, прямо здесь, указал на вас. Теперь вам необходимо объяснять дознавателям, где вы находились во время убийства и подготовки оной, присутствовать при обыске вашего жилища, искать свидетелей из НПС, которые могут подтвердить в ваши слова... В случае успеха в деле вы удостаиваетесь внимания и аудиенции у сановника, в случае провала партии придётся вас вызволять с эшафота!" },
      { from: 20, to: 20, text: "– Это он(-а), это он(-а)! – кричит кто-то, указывая на вас пальцем. Местная власть (будь то городская стража, узаконенная преступная группировка или телохранители местного правителя) схватят вас, не особо церемонясь, чтобы устроить длительный, скрупулёзный допрос о том, что вы делали последние два дня, требуя неопровержимые доказательства того, что вы не являетесь тем, кого в вас подозревают. Абсурд в том, что никто так и не сказал вам (и не скажет), в чем конкретно вас подозревали, но берегитесь, если у вас не получится договориться о взятке, или если, и того хуже, вы удумаете применить силу, чтобы выбраться из этой передряги." },
      { from: 21, to: 21, text: "Престарелый торговец из лавки редкостей / артефактов / зелий зовёт вас взглянуть на его товар. Вслух он отмечает, что многие считают его, старика, уже не тем, что в молодости, но своё дело знает. Очередная безделушка, которую он призывает примерить, или фиал, из которого он предлагает попробовать в качестве пробника, например, должны делать ваш голос зычным, мягким и притягательным. Вот только после применения вы стремительно... Превращаетесь в чёрного козла! Вы сохраняете способность мыслить как человек и получаете способность понимать и говорить на языке животных. Однако, общаться с разумными вы временно не способны... Как надолго? Что ж, старичок-лавочник, с невозмутимым выражением лица сходивший за моноклем и присмотревшийся к тому, что именно он вам дал, заявляет, что он перепутал фиалы, и, если эффект трансмутации не снять до следующего новолуния, он станет перманентным. Сам он знает зелье / обряд / амулет, который может снять эффект, однако для него необходимо раздобыть адуляр высокой чистоты и прозрачности... А пока ваши компаньоны занимаются его поисками, бросьте 1к8: эффект превращения спадёт сам собой через это количество часов. А вот способность понимать животных и характерные козлиные зрачки останутся: если не найти адуляр до новолуния - навсегда (эффект глаз - помеха ко всем видам социального взаимодействия, кроме Запугивания)." },
      { from: 22, to: 22, text: "В таверне к вам подсаживается или заводит разговор некий эльф. Знакомясь, он располагает вас к себе и приглашает за свой столик. Там, вместе с его товарищем, вы распиваете бутылочку эльфийского вина. Если вы пьёте, сделайте в процессе разговора спасбросок Телосложения (Сл 18). В случае неуспеха вы чувствуете резкое, но приятное опьянение. Постепенно эльф и его компаньон переводят разговор на вас. Оказывается, что они зарабатывают на жизнь торговлей амулетами. Прямо сейчас у них с собой крупная партия артефактов, и, если вы согласны подняться, они подберут что-нибудь для вас. Совершите проверку Проницательности (Сл 16, если вы употребляли алкоголь 18, если распивали предложенное эльфами вино - 20). Если вы не прошли проверку, вы не в силах сопротивляться уговорам приятных собеседников. Они берут вас под руки и ведут наверх... Наутро вы обнаружите себя в чужой комнате постоялого двора, в неглиже и в состоянии абстинентного синдрома, а также странные ощущения в области ниже поясницы. На столике в комнате будут стоять кувшинчик холодного пива, букет незабудок и короткое письмо, а на вашей шее будет висеть странный медальон. В письме содержится удивление, что вино так на вас подействовало, благодарность от обоих друзей за ночь и описание действия подарка (на выбор - Рука Вора (+1 Ловкость рук), Медовый Язык (+1 к Убеждению) или Крепкое Прясло (+1 к спасброскам Мудрости)). Эльфов вы не обнаружите, а трактирщик сообщит, что они уехали рано утром, извинившись за ночной шум." },
      { from: 23, to: 23, text: "Во время следующей попойки в трактире соседний столик признаёт в компании \"тех самых\", которые \"виноваты в свершениях\" и предлагают угоститься за их счёт. В процессе они достают кое-что особое - настойку корней мандрагоры и клобука монаха на гномьем самогоне. После один из них похваляется несравненной ловкостью рук: обнажив широкий кинжал, он шлёпает свою пятерню на стол и, сказав персонажу \"Эй! Смотри мне в глаза...\" начинает играть в \"чики-брики\", тыча ножом в просветы между пальцев, постепенно увеличивая скорость и не отводя глаз от глаз игрока. В какой-то момент он подкидывает кинжал, ловит за лезвие и предлагает персонажу повторить. Персонаж совершает спасбросок Интеллекта (Сл 18). В случае успеха, оппонент продолжает уговаривать: \"Да ладно тебе! Это не так сложно, как кажется!\" Персонаж должен преуспеть в спасброске Мудрости (Сл.18). В случае повторного успеха, оппонент не унимается и, ухмыльнувшись, называет персонажа трусом: спасбросок Харизмы (Сл 18). Если персонаж преуспел во всех трёх проверках, трое подвыпивших наёмников разочаровываются в партии и встретят их на выходе из трактира (ночью) или из города (днём), чтобы \"проучить трусливых хвастунов\". В случае провала персонаж соглашается и начинает играть. Оппонент также говорит, что смотреть нужно ему в глаза. Теперь персонаж должен преуспеть в трёх проверках Ловкости с помехой (Сл. 10, 14 и 18 - скорость-то растёт! а если персонаж тоже пил гномий самогон, сложность повышается на 2), после чего все смотрят на руку: сколько проверок провалено, столько пальцев персонаж случайно отрубил кинжалом боли он не чувствовал под воздействием мандрагоровой настойки! Пальцы, в целом, можно прирастить обратно, если ровно приложить их на место и использовать магическое лечение минимум на 2hp за палец. Сколько пальцев осталось к концу игры? Персонаж получает признание сотрапезников, шрамы на руке и прозвище [Имя персонажа][Количество оставшихся к концу игры пальцев] и мастерскую черту Гекки Четыре Пальца (Если вы начинаете попытку Запугивания со слов \"А ты знаешь, почему меня зовут [прозвище]?\" и демонстрируете шрамы на руке, проверка проходит с преимуществом)." },
      { from: 24, to: 24, text: "Касаясь кошеля на поясе, вы неожиданно осознаёте, что он звенит тише и стал на порядок меньше в весе и объёме, чем был до этого. Внутри вы с удивлением обнаруживаете скомканный клочок бумаги, маслянистый и пахнущий тыквой, на котором корявым почерком написано: «Клянусь третью своего урожая, я возмещу всё до последнего медяка!». Если каким-то чудом у вас есть возможность взять след по запаху, он приведёт вас на вскопанное тыквенное поле, где на вас нападёт одержимое магией пугало. Если этого не случится, то через пару дней вы обнаружите в своей комнате / возле своего спальника самую странную тыкву, которую вам только доводилось видеть в своей жизни. Внутри она будет набита вашими деньгами, но вонь от неё и от самих монет будет исходить несусветная." },
      { from: 25, to: 25, text: "Если кто-то из игроков отыгрывает откровенно злого, хаотичного персонажа (или творит анал-карнавал), во время следующего длительного отдыха ему будет видение: добропорядочное божество (или его общеизвестный представитель) является ему и говорит, что, де, он устал, что этот смертный ежедневно оскверняет его взор своими выходками. Игрока просят одуматься, покуда не стало поздно. Когда он повторяет что-то в своём духе в следующий раз, на небе подозрительно быстро сгущаются тучи и подозрительно близко от него незамедлительно бьёт мощный разряд молнии. Второй раз тучи сгущаются ещё быстрее, и молния бьёт ещё ближе. На третий раз молния мгновенно бьёт прямо в персонажа, нанося ему шоковый урон в 5к4 и на сутки парализуя левую или правую половину его тела. По прошествии суток чувствительность возвращается, однако у персонажа появляются две мастерских черты: Полупроводник (Ваш персонаж более устойчив к урону электричеством: снизьте такой урон на 1к6) и Астрапофобия (Герой приобретает боязнь молнии и грома. Если он слышит разряд грома или видит вспышку молнии, он должен совершить спаспбросок Мудрости или Харизмы со Сл 10. В случае провала он панически ищет укрытие, где бы он ни находился.)" },
      { from: 26, to: 26, text: "(ЭТА СЛУЧАЙНОСТЬ НЕ ПОДХОДИТ ДЛЯ ПЕРСОНАЖЕЙ ДВОРФОВ!!!) На пути вы натыкаетесь на сурового и явно сильно пьяного дворфа, мимо которого вам не удаётся пройти. Он молча и сердито смотрит на вас. Что бы вы у него ни спросили, в ответ он грубо просит вас замолчать, потому как он занят тем, что смотрит вам в глаза. На любую следующую вашу фразу он хватает вас за пояс и говорит: \"Ну всё...\", после чего поливает отборным набором брани. При попытке высвободится (Сл 18), вы будете слышать от него наблюдение, что \"у эльфов нет чести, нет уважения, нет пива\". Если вы всё же вырветесь и уйдёте, вслед вы услышите пожелание \"Хорошего денёчка!\". При следующей встрече (1к20 дней) тот же дворф попытается вас убить за \"нанесённое ему оскорбление\". Если же вы всё-таки примете бой, вне зависимости от его исхода дворф будет считать вас своим другом. Сам дворф не будет добивать вас, а у него имеется кольцо возрождения. Он происходит из уважаемого рода, и это знакомство может помочь вам во взаимоотношениях с другими дворфами. Кстати, его зовут Дастот сын Уриста." },
      { from: 27, to: 27, text: "Находясь в поселении, вы вдруг видите своё отражение в окне богатого дома, ведре либо бочке с водой, или в отполированном до блеска медном кубке, как вдруг осознаете, что на вас смотрит не ваш двойник, а мертвец с вашими чертами лица. Совершите проверку Мудрости (Сл 18). В случае провала, вы становитесь Испуганным по отношению к предмету, в котором увидели своё отражение. Ситуация будет повторяться каждый раз, когда вы будете видеть своё отражение в чем-либо. Начиная со второго провала спасброска, помимо состояния Испуганный, вы так же будете получать один уровень Истощения. Заклинание Снятие проклятья завершает этот эффект." },
      { from: 28, to: 28, text: "Пока вы прогуливались по улице, вас неожиданно схватил за руку молодой эльф. По его затуманенным глазам и расфокусированному взгляду в сторону вы понимаете, что он слеп. Загадочным голосом он предостерегает вас держаться подальше от пламени. Совершите проверку Мудрости (Сл 20). При провале, до конца дня с вами обязательно случится какая-то неприятность, связанная с пламенем, и вы получите 2к6 огненного урона. В случае успеха, вы не дадите себе настроиться на худшее, и избежите ожога – правда, пламя всё же подпортит вашу одежду." },
      { from: 29, to: 29, text: "Вы открываете рот, чтобы что-то сказать, как вдруг вас одолевает приступ сильнейшего кашля. Совершите спасбросок Телосложения (Сл 16). В случае провала, кашель оказывается настолько сильным, что у вас начинает стрелять в ушах, а из носа начинает капать кровь. Вы так же получаете 1к4 физического урона. Если бросок был успешным, вы чувствуете лишь острую боль в горле. Пытаясь объясниться перед отрядом, вы так же с ужасом осознаёте, что не способны издать ни звука. Целебные процедуры и зелья положительного эффекта не окажут: это проклятие. Заклинание Снятие проклятья завершает этот эффект. В противном случае, вам придётся искать помощь в поселении, в котором вы находитесь (или ближайшем к вашему лагерю). Проклятие на вас наложила жена городского целителя, который ни сном ни духом не ведает о том, как супруга помогает его делу." },
      { from: 30, to: 30, text: "Стайка детей окружает вас на улице. Пока одни просто кружатся хороводом вокруг вас с криками \"Нашлись! Нашлись!\", двое, мальчик и девочка, обнимают вас с криками \"Наконец-то! Папа нашёлся! / Мама нашлась!\". Вся сценка продолжается секунд десять, дети разбегаются. Сделайте проверку Внимательности (Сл 18). В случае неудачи вы поняли, что сорванцы умыкнули ваш кошель с пояса! Вычтите пятую часть своих денег." },
      { from: 31, to: 31, text: "У обочины сидит явно побитый тифлинг-оборванец и горько рыдает. При вашем приближении, он тянется к вам, хватает за полы одежды и умоляет ему помочь. Вид он имеет лихой и неприятный. Если же вы всё же собираетесь ему помочь, и он дотрагивается до открытого участка вашего тела, на ваших глазах происходит метаморфоза: лицо тифлинга преображается, приобретая более благородный вид, кожа даже меняет цвет, хотя следы побоев сохраняются. Чувствуя преображение, он удивлённо ощупывает своё лицо и, с радостными криками \"Лицо! Моё лицо! Я - снова я!\", убегает вдаль. Однако ваша партия может отметить, что теперь аналогичные превращения произошли с вами: вместо вашего привычного вида вы теперь выглядите как тифлинг, с чертами лица таковыми, что одна рука невольно тянется проверить, на месте ли кошелёк, а другая - к рукояти меча, на всякий случай. Если же кто-то сочувствующий дотронется до вас, проклятие аналогичным образом перейдёт с вас на него. Снятие проклятья поможет вам, а если вы сумеете отыскать убежавшего \"тифлинга\" - местного знатока законов и поборника справедливости, между прочим, - он поведает сложную историю взаимоотношений с одним из соперников..." },
      { from: 32, to: 32, text: "В начале следующей боевой сцены вы обнаруживаете, что ваш меч не выходит из ножен (опционально - спусковой механизм арбалета заедает, петля тетивы лука слетает, чудом не задевая вас). Совершите спасбросок Силы (Сл 12) с помехой, чтобы с усилием обнажить клинок (прожать спусковую скобу, надеть петлю в ушко), иначе вы остаётесь обезоруженным до следующего своего хода. На ближайшем привале потратьте не менее часа на ремонт ножен (механизма, тетивы), чтобы исправить это досадное неудобство." },
      { from: 33, to: 33, text: "Во время поедания мясной или рыбной пищи вы вдруг начинаете кашлять, потому что какой-то твёрдый предмет царапает вам горло. Получив 1hp урона, вы отхаркиваете его: это маленький гранёный самоцвет, ценностью в 1к20 золотых." },
      { from: 34, to: 34, text: "Сделайте спасбросок Ловкости (Сл 20). Откуда вообще здесь тяпка? Рядом нет ни одного огорода! В случае провала проверки, получите удар черенком в лоб (1к4 урона). Тяпка ваша." },
      { from: 35, to: 35, text: "Спустя час после последнего привала совершите спасбросок Телосложения (Сл 18) и повторяйте каждый час три раза. Если все три успешно пройдены - можете не беспокоится на счёт лёгкого урчания в животе. В случае провала кроме урчания вы чувствуете тошноту, лёгкое недомогание, а вскоре - озноб, жар и зов ближайших кустов. Кстати, вы вообще помните, где вы последний раз набирали воду? Если кто-то ещё в партии набирал её из одного источника, их ждут те же самые развлечения. Эффект заболевания длится сутки, на протяжении этого времени вы имеете состояние Отравлен. Впрочем, лечебное снадобье или божественное лечение не менее чем на 5 hp остановит течение болезни." },
      { from: 36, to: 36, text: "Совершите проверку Внимательности (Сл 18). В случае неудачи вы чувствуете, как вашу подошву прокалывает чтото острое. Получите 1к4 и совершите спасбросок Телосложения (Сл 14): в случае неудачи получите так же состояние Отравлен. Присмотревшись, вы обнаружите просто железное колечко с шипом, который недавно был смазан ядом..." },
      { from: 37, to: 37, text: "После очередного сражения с полудикими противниками (гноллами, гоблинами, кобольдами и т.п.) за вами следует некая птица, крик которой будто спрашивает вас: \"Кто? Кто?\" (или \"Имя?\", если больше похоже). Кроме того, она постоянно выдаёт врагам вашу диспозицию, саботируя ваши засады и провоцируя таковые для вас. Если вы поинтересуетесь у местных или совершите проверку Истории (Сл 14), вы сможете узнать, что у местных племён есть поверите о том, что некоторые воины, прошедшие особый ритуал, после смерти являются в виде таких птиц, которые станут преследовать вас до конца жизни, выпытывая имя убитого. Можно отправиться искать родное селение убитого, попытаться вычитать его имя на его снаряжении (если оно у вас), а можно попытаться подобрать имя простым перебором. Но помните! Имя нужно произносить с соответствующим произношением (для Мастера: подойдёт любое третье по порядку имя)!" },
      { from: 38, to: 38, text: "Убив некого шамана, колдуна или случайно активировав странный артефакт, вы чувствуете влияние некой ауры. Совершите спасбросок Телосложения (Сл 20). В случае провала, вы подвергаетесь страшному проклятью, подобному проклятью одного древнего царя: всякий металлический предмет, оказавшийся на расстоянии фута от вас, будь то амулет, кольцо, доспех, оружие или монеты, мгновенно обращается в свинец! Снятие проклятия спасает вас от этого эффекта." },
      { from: 39, to: 39, text: "Когда вы входите в очередное поселение, вы слышите крики \"Ловите его!\". На вас набрасывается некоторое количество местных жителей, вяжет и пытается утащить к местному законнику. Оказывается, что этих местах разыскивают опасного преступника, как две капли воды похожего на вас, за исключением какой-нибудь одной детали. По дорогам разосланы описания или висят \"ваши\" рисунки, так что ситуация однозначно повторится ещё несколько раз, если только вы не придумаете способ избежать недоразумений." },
      { from: 40, to: 40, text: "Пока вы шли по городской улице, за вами увязался малыш возрастом 6-9 лет. Он называет вас «папкой» и говорит, что наконец-то нашел вас. Когда вы расспрашиваете его, с чего он это взял, он выдаёт историю о том, как его умирающая мать отправила его именно в этот город, дав очень детальное описание того, как вы выглядите. Она пообещала ему, что вы за ним присмотрите и научите его сражаться на мечах / магии. Все проверки Проницательности показывают, что он говорит правду: пацан смышлёный и честно верит в то, что вы его «папка», и просто так не отстанет, сколько вы его бы не прогоняли. «А куда мне идти?», будет спрашивать он в очередной раз, когда вы почувствуете, что кто-то вас преследует. Городская стража и прочие органы власти уж точно будут на стороне мальца. Какие бы ни были у вас оправдания, горожане так же будут за ребёнка и начнут осуждать вас за любые выпады в его сторону. Действительно ли это ваш ребёнок, или это абсолютно нелепое недоразумение? На усмотрение мастера." },
      { from: 41, to: 41, text: "Любите наложить руки на чужое добро? Отныне в этом промысле вас ждёт нескончаемая чреда неудач, если только вы не совершите две удачные проверки для этого действия (Сл 18 у обеих). Стоит вам потянуться за чьим-то кошельком в толпе, как рука его хозяина вдруг скользнёт туда же и встретится с вашей. Пытаетесь стащить что-то, что плохо лежит? Неизбежно где-то рядом раздастся громкий звук, который привлечет внимание окружающих. А если рядом никого нет, а кошель так кстати покоится на книжной полке? Табуретка уж точно окажется с неустойчивой ножкой, и будет чудом, если эта самая полка потом не приземлится вам на голову. Чего уж говорить о дающих осечку, неожиданно срабатывающих ловушках – для них вы просто магнит какой-то! А всё потому, что не стоило воровать у очень мстительной феи, духа или чародея-трикстера, удумавшего вас проучить… Заклинание Снятие проклятья завершает этот эффект, но, если не попросить прощение или как-то загладить вину, оно вновь вернётся через сутки." },
      { from: 42, to: 42, text: "Этой ночью вам снится довольно необычный сон (если персонаж – эльф, то это видение окутывает его в процессе медитации), в котором вы оказываетесь в невесомости, посреди бесконечного пространства, наполненного тьмой и россыпью далёких звёзд. Но вы чувствуете, что вы здесь не один. Оборачиваясь, вы видите очертания ребёнка лет шести, тело которого будто соткано из мерцающей звёздной пыли, а глаза – словно два маленьких солнца, сияющих ярким фиолетовым пламенем. Когда он говорит, голос его раздаётся будто со всех сторон, а может – он общается с вами телепатически. Как бы то ни было, существо предлагает вам сыграть с ним в кости. Когда вы спрашиваете, на что вы будете играть – существо указывает на вашу грудную клетку. Опуская голову, вы видите небольшой мешок, который висит на верёвке у вас на шее, наполненный необычными, пульсирующими энергией камнями белого цвета. Когда вы поднимаете взгляд, вы видите точно такой же мешок у ребёнка, с той лишь разницей, что его мешок, как и само существо, сделан всё из той же пульсирующей светом пыли, а камни внутри такой же формы, что и ваши, но черные. Если вы отказываетесь играть, существо пожимает плечами и говорит: «Глупо», после чего вы просыпаетесь. Совершите спасбросок Мудрости (Сл 16). В случае провала, вы получите два уровня Истощения на день, а в случае успеха – лишь один. Если вы принимаете вызов существа, игра начинается. Сделайте ставку на количество камней из мешка (максимум – три за раунд). Бросьте 5к6. В случае, если у вас в сумме выпало больше 21, вы проиграли. Затем существо бросает 5к6. Если у существа выпало больше 21 очка в сумме, существо терпит поражение. Если у обоих игроков набралось менее 21-го очка на костях, и вы и существо можете перебросить 1 кость, но вы делаете это первым. Выиграет тот, у кого больше очков, но их сумма не должна превысить 21 – в этом случае наступает мгновенное поражение. Победитель забирает все камни. Затем весь процесс повторяется. Сущность признает вас победителем, если вы выиграете у неё более 10 камней. Вас же она будет пытаться обыграть до тех пор, пока вы не расстанетесь с 15. Если вы будете играть на равных, обыгрывая друг друга из раунда в раунд, после 6-8 раундов вы проснётесь от того, что вас трясёт за плечи член вашего отряда, спрашивая, всё ли с вами в порядке и почему ваше тело вдруг неожиданно начало мерцать фиолетовым светом. От чего бы вы ни проснулись, исход будет следующим: в случае победы над существом из вашего сна, вы получаете на трое суток временное увеличение максимального количества ваших хитов, равное значению выигранных черных камней. В случае поражения, ваше максимальное количество хитов падает на число проигранных белых камней - перманентно! Снять этот эффект можно лишь одним способом: отыграть камни назад, когда сон повторится спустя несколько ночей. В случае нежелания повторно играть в кости, с существом можно будет заключить другое пари или согласиться выполнить его поручение. Этот сценарий разворачивается на усмотрение Мастера." },
      { from: 43, to: 43, text: "Не стоило вам жалеть медяка тому нищему, который так проникновенно играл на городской площади. Вы даже не заметили, как эта мелодия засела у вас в голове: сперва вы просто настукиваете её костяшками пальцев... Затем мычите похожие звуки себе под нос... Но постепенно, она начинает сводить вас с ума, и через 2к4 часов она уже не выходит из вашей головы. Совершите спасбросок Харизмы (Сл 18), чтобы сопротивляться её пагубному влиянию на ваше сознание, и при провале получите уровень истощения. Совершайте эту проверку каждые к4 часов, получая по одному уровню истощения за каждый провал. На пятом уровне истощения вы просто впадёте в магическую кому, и не проснётесь до тех пор, пока проклятие не будет снято. Заклинание Снятие проклятья завершает этот эффект. Если вам повезёт, и вы или ваши соратники найдёте оскорбленного нищего до того, как это случится, он согласится снять проклятие за горсть золотых. В случае отказа, он растворится в воздухе, а спасброски на сопротивление мелодии вы станете совершать с помехой. Проклятие в таком случае так же будет сниматься с помехой." },
      { from: 44, to: 44, text: "Всё начинается с того, что у вас просто зачесалась нога. Подумаешь! Но уже через к4 часа, вы ощущаете в том месте небольшую шишку. Хорошие новости – это не рак; плохие новости – это устойчивый к магии паразит! Шишка очень быстро увеличивается, уже через к6+2 часов после появления она станет размером с яблоко, и на смену чесотке придёт боль. Ваша скорость уменьшится вполовину, а все проверки на Силу, Ловкость, Телосложение и Харизму будут совершаться с помехой. За каждый следующий час, ваш максимальный запас очков здоровья будет уменьшаться на 1 хит. За каждые снятые 5 хитов, вы так же будете получать уровень истощения. Никакая магия (кроме заклинаний 6-го уровня и выше) не способны справиться с паразитом. Всё, что вам нужно – найти хирурга и надеяться, что тот хорошо заботится о дезинфекции своих инструментов. Если вы согласитесь на обезболивающее во время операции (кроме удара молотом по голове), вас ждёт случайный побочный эффект: вы лишитесь на сутки одного из своих чувств или возможности говорить: совершите бросок к6, чтобы определить, что именно вас оставит (1 – осязание, 2 – обоняние, 3 – слух, 4 – зрение, 5 – вкус, 6 – голоса). Если же нет - вы не сможете снять истощение в ближайшие сутки из-за пережитых болезненных ощущений." },
      { from: 45, to: 45, text: "Во время очередной ночёвки под открытым небом ночью похолодало и прошёл мелкий дождь. Проснувшись под сырым одеялом вам захотелось согреться и потянуться. Совершите спасбросок Телосложения (Сл 18). В случае неудачи вы чувствуете резкую боль в мышцах в области поясницы. А вы что думали? Что прострелы бывают только у пожилых? Чтобы избежать болезненных спазмов, вам придётся совершать с помехой все проверки Силы, Ловкости и Телосложения. Всякая попытка активной деятельности, будь то бег, атака или что-то подобное, обернётся для вас спасброском Телосложения (Сл 14), провал которого приведёт к болезненному спазму и состоянию Обездвиженный (спасбросок Сл 14 спасает). Чтобы избавиться от прострела, вам необходимо получить магическое лечение не менее чем на 8 hp либо провести длительный отдых под присмотром лекаря." },
      { from: 46, to: 46, text: "Совершите проверку Природы (Сл 10). Вы обнаруживаете некое местное редкое цветущее растение (в холодное время - живые коренья или грибы), о котором вы слышали, что отвар из оного улучшает кровоток, наделяя руку крепостью, а глаз - зоркостью (т.е. Сила и Ловкость +1). Если вы употребляете этот отвар, совершите спасбросок Телосложения (Сл 20). Оказывается, вы ошиблись: это действительно редкое местное растение, вот только его целительная сила проявляется в исключительно слабых растворах. Отвар же из него ядовит: в случае провала вы получаете состояние Отравленный (держится трое суток) и одну степень Истощения. В случае же успешного спасброска вы действительно получаете бонус к Силе и Ловкости (эффект держится трое суток), а если результат того самого первого броска Природы был 21 и выше - сразу распознаёте своё заблуждение." },
      { from: 47, to: 47, text: "Среди ночи вы замечаете призрачный силуэт подле себя. Это привидение последнего убитого вами разумного существа. Оно не нашло упокоения и теперь мстит вам, являясь по ночам, мешая спать и рассказывая о том, что сейчас происходит с его останками, вспоминая других, умерших от вашей руки. Что характерно, другие герои его не видят, и только Обнаружение добра и зла (Сл 18) способно засечь странную эманацию, исходящую от вас самих. Из-за причиняемых призраком неудобств каждый день вы получаете одну степень истощения. Изгоняющие заклинания не принесут пользы, но исповедь, молитва об упокоении души умершего, принесение жертв и кенотаф (символическое захоронение) помогут вам успокоится." },
      { from: 48, to: 48, text: "Во время странствий к вам прибивается некий субъект, утверждающий, что он начинающий бард / художник, ищущий объект вдохновения. Почему-то очень скоро его вдохновляет именно ваша фигура и именно ваши похождения. Спустя день-другой он принимается за труд: в ближайшем же селении жители будут покатываться со смеху от его пашквилей в ваш адрес или шаржей, комедийно обыгрывающих все ваши подвиги. На все ваши возражения, он будет упрямо утверждать, что за сатирой будущее, это искусство, а вы - ничего не понимаете!.." },
      { from: 49, to: 49, text: "Среди ночи вы просыпаетесь от чьего-то шёпота, ощущая рядом присутствие кого-то ещё. Открыв глаза, вы обнаружите над собой соблазнительного суккуба / инкуба, который прикладывает палец к губам, призывая вас вести себя тише. Совершите спасбросок Мудрости или Харизмы (Сл 18). В случае провала вы поддаётесь демоническим чарам и предаётесь утехам. Следующей ночью демон является снова. Спасбросок совершается уже с помехой (Сл 18). Если вы провалите эту проверку, новая ночь с демоном принесёт вам 1 уровень истощения, а если ранее вы не обмолвились никому из своих соратников об экзотической встрече, то обнаруживаете, что вам необходимо усилие воли, чтобы вспомнить об этом событии (проверка Мудрости с помехой, Сл 14). Каждую следующую ночь демон будет возвращаться, сложность спасброска против его чар будет расти на 1 пункт, и даже если вам удастся избавиться от него сегодня, это не значит, что он не навестит вас завтра. Каждый же акт любви с демоном будет дарить вам ещё один уровень истощения. Остаётся уповать лишь на то, что ваши сопартийцы успеют понять, что дело нечисто, раньше, чем ваши силы иссякнут." },
      { from: 50, to: 50, text: "Пока вы идёте по городскому рынку или обмениваетесь слухами с местным трактирщиком, к вам на уши припадает невысокий лысый эльф в скромных монашеских одеждах. Сперва разговор не предвещает беды: мужчина больше интересуется вами, а особенно – вашими жизненными и религиозными убеждениями. Но, чем больше вы раскрываетесь – тем охотнее ваш собеседник говорит о себе и своих религиозных убеждениях. Совершите спасбросок Харизмы (Сл 20). В случае провала, вы начинаете чувствовать симпатию к деятельности его ордена, да и в целом он располагает вас к себе своими беседами (вы становитесь Очарованным вашим собеседником). Все следующие проверки Харизмы будут совершаться с помехой. Повторите спасбросок Харизмы. В случае провала, вы чувствуете необходимость угостить вашего нового друга выпивкой, ведь он, оказывается, столько благих дел совершает для этого мира, вы даже начинаете испытывать лёгкий стыд за то, что проявляете не так много усердий в помощи тем, кому повезло меньше вашего. Повторите спасбросок Харизмы. В случае провала, вы осознаёте, что единственный шанс исправиться – немедленно сделать достойное пожертвование на дела ордена вашего нового лучшего друга (не менее 20% ваших текущих накоплений, и треть драгоценных камней, если они у вас имеются). Повторите спасбросок Харизмы. В случае провала, вы осознаёте, что ваша встреча не была случайной, и просите принять вас в Орден. Ваш собеседник одаривает вас лучезарной улыбкой и протягивает магический контракт, в котором вы бездумно, моментально расписываетесь. С этого дня, пятая часть любых ваших доходов принадлежит Ордену, но узнаете вы об этом лишь тогда, когда ознакомитесь со своей копией подписанного документа – к этому времени, вашего нового знакомого и след простынет. Через час после его исчезновения, состояние Очарованный проходит само собой, и вы осознаете всё, что с вами произошло, но пути назад нет: вам придётся передавать часть своего заработка в казну ордена, или столкнуться с последствиями невыполнения договора. Насколько они будут тяжелые, решает мастер." },
      { from: 51, to: 51, text: "Каждую ночь вы просыпаетесь от какого-то лёгкого звука. Совершите проверку Внимательности (Сл 18). В случае успеха вам кажется, что вас кто-то тихо, но настойчиво призывает. Продвигаясь прочь от стоянки или места ночлега в темноту, вы обнаруживаете источник зова небольшой тёмный объект, застывший в воздухе над землёй. Присмотревшись, вы понимаете, что эта точка пространства буквально источает Тьму, сочится ею, но главное - Тьма эта живая, и именно она призывает вас и сейчас наблюдает за вами... Совершите спасбросок Мудрости (Сл 18). В случае провала вы получаете 2к6 психического урона и состояние Недееспособный на 1к8 часов. В случае успеха вы получаете 3к4 психического урона, состояние Недееспособный на 2к8 часов и состояние Ошеломлён на следующие сутки. Также получите авторскую черту Смотрящий во Тьму (Вы обретаете способность видеть в абсолютной темноте, даже в магической тьме. Каждый раз, используя эту способность, вы получаете помеху ко всем прочим проверкам Внимательности, а по окончании вынуждены совершить спасбросок Телосложения (Сл 14), в случае провала которого вы получаете 1к4 психического урона)." },
      { from: 52, to: 52, text: "Ночью вам приснился сон, в котором вы спасли супругу местного правителя от совершенного на их семью покушения, и, в знак признательности, вам было дозволено взять из казны столько золота, сколько вместится в выданный вам мешок. Пользуясь редчайшей возможностью разбогатеть, вы набили его под завязку, да так, что он уже попросту не мог завязаться: вы крепко пытались сжать его горлышко, пока монеты сыпались сквозь ваши ладони, как вдруг… Вы просыпаетесь и понимаете, что ваши руки сжимают не твёрдые горсти монет сквозь хлопчатую ткань, а что-то мягкое и тёплое. Вы с ужасом осознаёте, что всё это время, находясь во сне, вы душили члена своего отряда, а самое ужасное в этой ситуации было то, что в этот самый момент его глаза открыты в панике смотрят на вас. Пусть он совершит спасбросок Силы (сложность: показатель силы персонажа, который его душил), чтобы понять, удастся ли ему вырваться из вашей хватки сейчас, когда вы пришли в себя, но всё ещё не осознали, что творите. В случае провала, он получает 2к4 дробящего урона, и половину этого урона в случае успеха, при котором он освобождается из захвата." },
      { from: 53, to: 53, text: "Когда вы добиваете очередного противника, будь то разумное или неразумное существо, вы чувствуете пульсацию в висках, запах крови и опьяняющее чувство собственного превосходства... А также животный страх за то, что окружающие могут на это превосходство покуситься. Совершите спасбросок Харизмы (Сл 18). В случае провала вы входите в ярость, получая одну кость временных хитов и атакуя любое ближайшее существо, будь то друг или враг. Атаки ваши совершаются с помехой, но в случае попадания вы наносите 1к4 дополнительного урона. Это состояние длится 3 раунда, после чего продолжается ещё на раунд, если вы получили или нанесли хотя бы 1 hp урона. Состояние прекращается после того, как вы потеряете сознание. Но кто даст гарантию, что оно не повторится?" },
      { from: 54, to: 54, text: "Пока вы гуляли по городу или обедали в трактире, к вам цепляется шайка эльфийских наёмников. По их внешнему виду вы понимаете, что они выжили не в одной дюжине сражений, а теперь стоят перед вами с настороженными выражениями лиц и опасно прищуренными глазами, требуя показать, что находится у вас в сумке. В случае отказа, они это так не оставят, и даже если их удастся прогнать какимто способом, они устроят на ваш отряд засаду или нападут где-то в другом месте. В случае согласия, вы демонстрируете содержимое своей сумки и с удивлением для самого себя обнаруживаете там небольшую костяную статуэтку, которую никогда прежде не видели. Эльфы потребуют вернуть её им. В случае отказа эльфы уйдут, но последствия себя ждать не заставят. Как бы вы ни поступили, через некоторое время ваш отряд встретит пожилую гномку, которая поблагодарит вас и вежливо попросит отдать статуэтку ей. В случае отказа, она усыпит всех вокруг чарами и спокойно её заберёт. В возмещение она оставит вам обычный магический предмет. Если вы отдали статуэтку гномке по доброй воле, к нему прибавится так же кошель, наполненный серебряными монетами (количество – на усмотрение Мастера)." },
      { from: 55, to: 55, text: "Во время трапезы в трактире или на постоялом дворе, вы вдруг почувствовали резкую боль во рту: у вас раскололся зуб. Сперва это кажется ерундой, но через некоторое время вы чувствуете, как щека начала опухать. К счастью, в городе есть практикующий зубной лекарь, которого вы не без труда находите в портовом районе или в районе для бедняков. Договорившись о цене, он даёт вам обезболивающую пилюлю и приступает к осмотру больного зуба. Через некоторое время вы чувствуете, как вас начинает клонить в сон, и под слова о том, насколько прекрасно состояние остальных ваших зубов, вы отключаетесь (даже если вы – эльф, т.к. сон от снотворной пилюли не является магическим). Проходит к4+1 часов, прежде чем вы придёте в чувства и обнаружите себя с застывшей на лице кровью, металлическим привкусом во рту и головной болью. Пока вы спали, вам было нанесено к6+2 урона недобросовестными действиями шарлатана, который повыдёргивал у вас 2к8+2 здоровых зубов. Причем, больной зуб он оставил на месте. С этого момента, вы получаете штраф -4 к Харизме, а все проверки навыков на её основе совершаются с помехой. От этого состояния вас сможет избавить лишь порядочный зубной врач, но обойдётся вам это в кругленькую сумму." },
      { from: 56, to: 56, text: "Во время прогулки по городу или даже за его пределами, на вас неожиданно нападает дикая собака: животное прокусывает вам руку или впивается в шею, после чего скрывается. Совершите спасбросок Телосложения (Сл 14). В случае провала, вы заражаетесь скоротечной формой Бешенства со следующими симптомами: через 2к6 часов, у вас начнутся дыхательные спазмы (персонаж получает 1 уровень истощения); ещё через к4 часа, персонаж становится возбуждённым и агрессивным (проверки навыков и спасброски совершаются с помехой); каждый последующий час, персонаж получает ещё по одному уровню истощения, из которых 6-ой – летальный. Это состояние может завершить заклинание Малое восстановление или другие целительные чары, а также зелья лечения болезней. Но это не всё… Вне зависимости от того, заразились вы бешенством или нет, ночью вам снится крайне тревожный сон, в котором вы преследуете свою жертву, причем делаете это на четвереньках, словно дикий зверь. На этом странности не заканчиваются: с утра вас одолевает животный голод, а к обеду вам кажется, что ваши зубы стали острее. Совершите проверку Интеллекта (Сл 5). В случае успеха, вас озаряет: животное заразило вас ликантропией. Хоть это и не так, вы убеждены, что правы, поэтому все проверки на обнаружение настоящих признаков болезни будут совершаться с помехой (т.е. в случае провала будут подтверждаться ваши страхи, что вы заражены). Вы так же убеждены, что раскрывать правду о своих подозрениях опасно даже ближайшим союзникам, поэтому каждый раз, когда вы пытаетесь это сделать, вы становитесь Испуганным по отношению к тому, кто вас подозревает или кому вы почти решились открыть правду. Пик паранойи наступит в ночь полнолуния, но, когда с вами ничего не произойдёт, вы наконец избавитесь от своих навязчивых страхов." },
      { from: 57, to: 57, text: "Когда вы прогуливаетесь в городе, с вами сталкивается какой-то подозрительный типчик. Совершите проверку Внимания (Сл 18). В случае удачи, вы успеваете заметить, что он пытается забросить вам в карман / за пояс / за пазуху / в сумку небольшой кулёк пергамента. В ином случае, огрызнувшись на растяпство, он движется себе дальше. Буквально через минуту к вам подойдут два стражника и попросят показать содержимое ваших карманов. Найдя и открыв кулёк, вы обнаружите там мускатные орехи, перец, шафран, мирт, асафетиду или любые другие привозные специи. Вот только тонкость в том, что любая торговля этими самыми специями в любых количествах в городе запрещена. В качестве санкции к нарушителю применяется либо т. н. торговая казнь - день в колодках на площади, либо значительный штраф в виде десятикратной стоимости обнаруженных у вас специй." },
      { from: 58, to: 58, text: "На привале вам снится сон. Он настолько реален, что, проснувшись, вы не сразу осознаёте, что бодрствуете. Вам снилось, что ваши таланты покинули вас (провал всех проверок по самой высокой характеристике). Теперь, совершая всякую проверку данной характеристики или навыка, с ней связанного, вы должны совершить спасбросок Мудрости. Три успеха снимают с вас морок. Три провала же убеждают вас в том, что вы и впрямь вовсе не так хороши, как думали всё это время: получите штраф -2 к данной Характеристике. Снять его может очищающее действие: посещение храма, омовение в священном источнике, жертва духам и пр." },
      { from: 59, to: 59, text: "Не стоит долго смотреть в зеркала, особенно в те, что стоят в подозрительных лавках в неблагополучных районах города, заваленных кучей старинных предметов самых странных форм, которые мало что говорят об их назначении. Но вернёмся к зеркалу... Пока вы смотрели в него, ваше отражение вдруг перестало повторять ваши движения, решив продемонстрировать довольно оскорбительный жест и просто сбежать от вас подальше. Совершите спасбросок Мудрости (Сл 14), при провале которого вы в ужасе побежите в противоположную сторону от проклятого предмета. Даже если вы устоите, очень скоро вас ждёт новый повод испугаться: вы вдруг понимаете, что остались совсем одни посреди лавки, а все ваши сопартийцы находятся там, за отражением зеркала, рассматривают товары, глядят на вас сквозь его поверхность, или вообще пустились догонять сбежавшего двойника... Вернее, ваше отражение, которое умудрилось покинуть зеркало, заперев вас внутри." },
      { from: 60, to: 60, text: "Сперва вам кажется, что кто-то пытается связаться с вами телепатически: вы слышите голос внутри своей головы, хоть и не можете понять, что именно он говорит – он будто приглушен или звучит где-то очень глубоко. Но вскоре он становится четче, и вы убеждаетесь: говорит он именно с вами. Причем он от вас, мягко говоря, не в восторге: его просто прорывает на критику всего, от вашего внешнего вида, до решений, которые вы принимаете. Совершите проверку Интеллекта (Сл 15). В случае успеха вы понимаете, что голос не просто раздаётся в вашей голове: его источник находится внутри вас. Но кто же это может быть? Пробудившаяся душа, возможно? Или мелкая тёмная сущность? А может, вы медленно сходите с ума? На усмотрение мастера." },
      { from: 61, to: 61, text: "Перед вами очередной трактир. Желая промочить горло, вы входите внутрь и... Вынуждены совершить спасбросок Ловкости (Сл. 18). В случае неудачи, кроме крика \"Ты посмел вернуться?\" в вашу сторону летит кулак полуорка-вышибалы, причиняющий вам 2к4 урона и выбивающий одним махом за дверь. Недовольство вашим появлением разделяют так же трактирщик и некоторые гости. Все как один кроют вашу персону последними словами, говорят, что более не потерпят ни такого хамства, ни такого разорения, как вчера, и вообще готовы звать стражу и применять оружие. Собственно, проходящий рядом наряд стражи удивляется ещё больше и пытается вас задержать. По мнению стражи, они это уже сделали сегодня под утро и лично сопроводили вас в камеру, а, следовательно, за побег вам тоже причитается. Однако они готовы (и могут!) устроить вам очную ставку с предыдущим задержанным." },
      { from: 62, to: 62, text: "Сегодня вы явно встали не с той ноги. Буквально… не со своей ноги. Проснувшись, вы с ужасом осознаёте, что вы – это не вы: каким-то волшебным образом, пока вы спали, ваше тело пережило метаморфозу, и вы обрели все внешние признаки противоположного пола. Что примечательно: вы не просто поменялись телами с кем-то, о нет! Как только вы увидите своё отражение, вы поймёте, что полностью сохранили характерные черты своего прежнего облика, за исключением лишь частичной гендерной трансформации. Но что же произошло ночью? К несчастью, ответа на этот вопрос вы не получите в ближайшие часы, сколь усердно бы вы ни искали следы или свидетелей. Лишь поздней ночью этого дня, к вам приблизится некая тень в тёмном переулке, или, когда вы останетесь одни в своей спальне, или разбудит вас, пока все ваши товарищи будут спать в своих спальниках… Потревоживший вас протянет вам небольшое зеркало в деревянной оправе, и когда вы посмотрите в него, вы увидите себя таким, каким были прежде. В этот самый момент вы обнаружите, что чары сняты, и всё вернулось на свои места. Мужчина окажется истинным вампиром, крайне вежливым, если опустить обстоятельства, предшествующие вашей встрече. Он принесёт вам свои извинения и расскажет, что это было небольшое пари между ним и его «близкими друзьями». Он протянет вам зачарованный медальон в знак компенсации за моральный ущерб. В качестве альтернативы, если он не увидит признаков агрессии или невежества, и, если вы вели себя достойно весь день и сумели произвести на него впечатление или удивить, он предложит вам дар бессмертия. Но, быть может, это всего лишь очередное пари?" },
      { from: 63, to: 63, text: "Сегодня вам явно нездоровится. Вы чувствуете общую слабость, ломоту в суставах и явный тремор конечностей, отчего становится крайне затруднительно совершать всякую мелкую работу, а резкие движения отдаются болью. Совершите спасбросок Телосложения (Сл 18): в случае успеха, ваши страдания окончатся к вечеру, иначе недуг затянется на 1к4 дней. В любом случае, он сопровождается штрафом -4 к вашей характеристике Ловкости. Если вам не посчастливилось отделаться от болезни одним днём или снять её симптомы любым другим лечением, на следующий день после естественного выздоровления вы получаете приятный временный бонус +1 ко всем проверкам, основанным на Ловкости!" },
      { from: 64, to: 64, text: "Вы с самого утра чувствуете какую-то лёгкость в голове, некую пустоту и рассеянность. Возможно, вас выдаёт расфокусированный взгляд, который настораживает ваших напарников. Совершите спасбросок Харизмы, когда услышите своё имя (Сл 18). В случае провала, вы отключаетесь на к10 минут, или пока вас не приведут в чувства. Если вам будут пытаться помочь прийти в себя, и начнут звать вас по имени – все проверки автоматически будут считаться проваленными. Как сознание вернётся к вам, вы не будете помнить, как и почему лишились его – весь эпизод блокирован в вашей памяти. Повторяйте спасброски Харизмы каждый раз, когда услышите своё имя. Как только вы осознаете, что вызывает этот феномен, проверки Харизмы станут совершаться с помехой, но в себя вы начнёте приходить уже без потерь памяти. Это не проклятие, это некий сбой в работе вашего мозга, поэтому состояние может быть устранено целебными чарами шестого круга и выше. Оно так же пройдёт само через 8 часов крепкого, непрерывного сна." },
      { from: 65, to: 65, text: "Поравнявшись с дверями местной таверны, вы внезапно почувствовали, как вас схватили за локоть. Не успели вы оглянуться, как рассерженная молодая женщина с неожиданной силой и словами о том, что вас уже обыскались, потащила вас в таверну, на ходу покрывая вас отборной руганью. Любая проверка характеристик или навыков с попыткой возразить или вырваться автоматически провалена: не слушая попыток возражать, женщина заталкивает вас за занавесь кухни, где другие работники всучивают вам одежду и передник полового, одновременно снимая с вас снаряжение. После краткого напутствия вас выпинывают работать в зал! Пройдите проверку Выносливости и Харизмы, чтобы узнать, насколько хорошо вам удалось освоиться в роли работника трактира. Провалив проверку Выносливости, вы от усталости спотыкаетесь и обливаете важного гостя пивом. Вас лупят его подручные и забирают 1к10 золотых в качестве компенсации. Провалив проверку Харизмы, вы злите хозяйку заведения своей постной рожей, и она оставляет вас здесь ещё на день, чтобы научить уму-разуму. Успешно пройдя проверки, вы завершаете смену, и наконец выходите из трактира, заработав по 1к4 серебра за каждый балл выше сложности проверки, но получаете один уровень Истощения. Однако, выбросив критический успех при проверке Выносливости, этого можно избежать, даже если вы задержитесь тут ещё на день. Выбросив критический успех проверки Харизмы, вы очаровываете одну из работниц трактира и проводите поистине бурную ночь: получите один уровень Истощения. Получите очко вдохновения и совершите проверку Телосложения (Сл 8): при провале вы подцепили дурную болезнь и нужно лечение." },
      { from: 66, to: 66, text: "Когда вы располагаетесь спать вне цивилизации, всё кажется обыденным. Когда приходит ваш черёд спать, вам снится сон о том, как вы медленно плывёте куда-то, лёжа лицом вверх, наблюдая за небом. Однако, в какой-то момент вы ударяетесь головой о камень и понимаете, что ваши ноги опутаны лианами / кореньями, которые тащат вас прочь от лагеря!" },
      { from: 67, to: 67, text: "Вы решили потратить честно (или не очень) заработанные богатства и купить себе нечто ценное, что принесёт немало пользы в ваших странствиях - оружие, зелья, или какой-то магический предмет у странствующего торговца чарами. Какая удача! Вам удалось найти редкость по очень справедливой цене. К сожалению, вскоре вы понимаете, что вас просто обвели вокруг пальца: меч расколется в сражении из-за некачественного сплава, зелья окажутся просроченными, а волшебный предмет и вовсе даст осечку, активировав волну непредсказуемой дикой магии. Доверяй после этого гномам! Взамен вы получаете +1 к проверкам Проницательности при торговых операциях." },
      { from: 68, to: 68, text: "Сегодняшнее утро начинается для вас с ужасной боли: ни с того, ни с сего у вас отворились раны, полученные вами в недавних боях. Бросьте 1к12+1 - столько новых ран открываются на вашем теле. Раны кровоточат, снижая количество ваших максимальных хитов на 1 каждая. Удивительно, но никакое лечение (кроме прямого божественного вмешательства) не приносит вам облегчения, догадка о проклятии также не оказывается верной. Зато Поиск добра и зла покажет нависающий над вами венец злой божественной сущности. В конце каждого следующего дня совершайте проверку Телосложения (Сл 10): в случае успеха одна рана закрывается (в случае критического успеха - две), в случае неудачи количество максимальных хитов снижается ещё на 1 (в случае критической неудачи - на 2). Чем же вы так прогневили божество?.." },
      { from: 69, to: 69, text: "Среди ночи вы слышите доносящуюся издалека мелодию. Совершите проверку Мудрости (Сл 16). В случае провала, вы, заворожённый её звучанием, идёте проверить, где находится источник шума. Очень яркая луна в ночном небе освещает вам путь. Ступая в её свете, как по дороге, вы бредёте в ночи на источник всё усиливающейся музыки. Вскоре вы начинаете слышать и прекрасное пение. Совершите вторую проверку Мудрости (Сл 18). В случае провала, пение мёдом разливается по вашему телу и зовёт к себе. Вскоре вы набредаете на поляну, где вокруг костра всех цветов радуги танцуют, веселятся, пьют и предаются любви прекрасные существа - эладрины и феи. Один из них замечает вас и зовёт присоединиться к веселью, ведь сегодня большой праздник - Ночь Силы. Он принимает большую чашу, которую они передают по кругу - это Лунный Мёд, праздничное питьё, которое он предлагает и вам, как гостю. Совершите последнюю проверку Мудрости (Сл 20). В случае провала, вы делаете глоток, после чего ваши воспоминания смешиваются. Так или иначе, после любого успеха или последнего провала ваши товарищи обнаружат вас в отдалении от того места, где вы остановились на ночлег. Вместо вашей обычной одежды на вас будет длинная рубаха из тонкого шёлка. Вы не помните никаких подробностей произошедшего... Однако, если вы испили Лунный Мёд, ваши товарищи обнаруживают, что вы изменились: постарели на 10 лет, а в лунном свете отныне на вашем лице вспыхивают серебром татуировки, изображающие витиеватый узор. Неизвестно, что именно происходило с вами в Стране Фей, однако время это не прошло зря: получите одну черту, требованиям которой вы отвечаете." },
      { from: 70, to: 70, text: "Во время посиделок в очередной таверне или постоялом дворе держатель заведения с сочувствием обратит внимание партии на ребёнка лет 7-8, который играет у входа или работает на посильной чёрной работе. Хозяин заведения расскажет, что малец странствовал со своим отцом, который занимался не самыми лучшими делами: был бандитом / контрабандистом / наёмником. Из описания игроки могут понять, что знали покойного: именно они убили его во время своей последней стычки. Узнав же, куда именно держит путь отряд, хозяин заведения очень радуется: ведь со слов ребёнка именно по пути туда должен жить кузен его отца! Если после долгих уговоров и взывания к совести партия соглашается, малец присоединяется к ним. Когда же они добираются до места, то находят там захудалое хозяйство: старую лесопилку, ферму, претерпевшую растительный мор или падёж скота и т.п. При этом сам кузен, хозяин дома, оказывается пьяницей, скверный характер его жены слышно ещё на подходе, а их дети вовсе не выглядят сытыми и счастливыми. Оставить ли ребёнка здесь - решать игрокам." },
      { from: 71, to: 71, text: "Народная примета гласит, что, если на вас нагадила птица это к деньгам. И теперь у вас есть возможность убедиться в этом! Трижды в день сделайте бросок к20: при результате ниже 10 на вас обильно гадит местная птица (если вы далеко в море - на вас мечет икру летучая рыба / волна из-за борта выносит на вас \"молодую амбру\" (китовый кал); если это подземелье - опасайтесь гуано летучих мышей). Вещество так въедается в одежду, что видом и запахом демонстрирует окружающим вашу неудачу: любая ваша проверка Харизмы переносит помеху. Но! Сделайте ещё один бросок к20: столько медных монет вы находите! К слову, это не проклятье: животные по непонятным причинам действуют целенаправленно и сообща..." },
      { from: 72, to: 72, text: "На ближайшем рынке или в селении стоит торговец, который торгует крепкими напитками. Среди прочего, он устроил дегустацию некоторых напитков, отмечая, что тот, кто обнаружит на дне своей чарки бронзовую монетку сможет продегустировать его особое изделие. И именно вашему герою везёт! Торговец держит слово и выуживает из сундучка небольшой штоф с маслянистой жидкостью, отливающей медью и патиной и издающей тяжеловатый аромат древесной камеди и холода. Сам торговец называет эту настойку \"универсальным средством для понимания на любом застолье\". Напиток мягко уходит по пищеводу, прогревает нутро, что вам нравится. Однако, через мгновение вам начинает очень неприятно жечь и покалывать язык. Неважно, чем далее закончится встреча с торговцем. Важно другое: в течение часа вы внезапно осознаёте, что можете понимать на слух только всеобщее наречие и... язык тортлов / аарококра / гноллов, а изъясняться самостоятельно можете только на последнем. Эффект изменится следующим утром: первый, кто заговорит с вами на языке, отличном от \"вашего\", \"подарит\" вам способность понимать и говорить на этом наречии. Эффект продолжается неделю, в течение которой вы увеличиваете число языков, которыми \"владеете\". По прошествии недели эффект спадает, и вы снова изъясняетесь на тех языках, которыми владели до дегустации." },
      { from: 73, to: 73, text: "Блуждая по улицам поселения, вы останавливаетесь, чтобы оглядеться и сориентироваться. Вдруг в вашу ногу что-то мягко упирается: взглянув вниз, вы видите некрупную кошку, которая смотрит вам прямо в глаза. Пройдите проверку Ухода за животными или Природы (Сл 10). В случае провала вы отправляетесь дальше по своим делам. В случае успеха вы понимаете, что она зовёт вас за собой. Спустя какое-то время вы протискиваетесь вслед за кошкой в узкую тёмную щель между домов. Неожиданно, по ту сторону находится совершенно другое место: залитая светом поляна с высоким деревом, похожим на фиговое или пальмовое. Пока кошка движется прямо к дереву, совершите проверку Внимательности (Сл 16), чтобы заметить, что у неё необычные лапки для кошек - пять пальцев не только на передних, но и на задних конечностях, и понять, что кошка - не просто животное. Подойдя за ней к дереву, вы видите крупный мясистый плод на ветвях. Кошка как будто просит достать его. Вы можете сорвать фрукт. С первым же касанием вы чувствуете сочащуюся из фрукта мощь, которую можно поглотить. Кошка смотрит на вас и снова трогает лапкой, прося дать его ей. Совершите проверку Мудрости (Сл 14). В случае успешного преодоления искушения, вы отдаёте кошке фрукт. Она довольно урчит, трётся о вашу руку головой и принимается за фрукт. Съев его, она обращается красивой женщиной с кошачьими ушами и хвостом, одетую в простое лёгкое платье и золотые украшения (проверка Религии Сл 14, чтобы узнать богиню Шихерез). С благодарностью и поцелуем в щёку она обещает присматривать за вами, после чего тихо исчезает. Получите черту Любимец Шихерез (Ловкость и Харизма увеличиваются на 1, ко всем проверкам удачи также прибавляется 1). Эффект бессрочный, но мгновенно превратится в проклятие с теми же отрицательными эффектами, если вы будете жестоко обращаться с кошками или нападёте на кошку первым. Если искушение перед плодом сильнее вас, вы съедаете плод. Кошка шипит и убегает. Прилив сил застилает глаза красной пеленой: ваша Сила и Выносливость увеличиваются на 1. Также вас настигает проклятие кошачьей богини, описанное выше. Его можно снять, но тогда бонус Силы также пропадёт, а вы получите уровень Истощения." },
      { from: 74, to: 74, text: "Вода из последнего источника (или кружка \"особого эля\" в последнем трактире) имела необычный привкус. Совершите проверку Телосложения (Сл 18). В случае провала, вы чувствуете уверенность в том, что ваше тело переполняет магия, а мозг буквально кипит от знаний: получите состояние Очарованный на ближайшие 1к4 дней, на это время Интеллект становится вашей основной характеристикой ко всем проверкам Атак, включая заклинания. Если вы не снимаете это состояние магией или божественным вмешательством, в последний день недуга вы чувствуете заметное улучшение: получите +1 к спасброскам и проверкам Интеллекта на ближайшие 1к4 дней. Кроме того, вы получаете перманентное владение заговором Фокусы, если ранее не знали его." },
      { from: 75, to: 75, text: "Спасаясь от зноя или слепящего света вы шагаете в тень... И неожиданно понимаете, что это Теневое существо (Shadow), которое застаёт вас врасплох! Но откуда оно здесь?.." },
      { from: 76, to: 76, text: "Вода из последнего источника (или кружка \"особого эля\" в последнем трактире) имела необычный привкус. Совершите проверку Телосложения (Сл 18). В случае провала, вы чувствуете себя неважно: получите состояние Отравлен на ближайшие 1к4 дней. Если вы не снимаете это состояние магией или божественным вмешательством, в последний день недуга вы чувствуете заметное улучшение: получите +1 к спасброскам и проверкам Телосложения на ближайшие 1к4 дней." },
      { from: 77, to: 77, text: "Сбившийся с ног гонец доставляет вам письмо, запечатанное в кожаный тубус. Внутри - карта сокровищ, бумаги на получение наследства или уведомление о лотерейном выигрыше (если сеттинг такое предусматривает), с комментарием от вашего старого компаньона или родственника о том, что пришлось отправить гонца, т.к. держание этих бумаг оказалось небезопасным. Вскоре у вас будет возможность убедиться в этом. Очень настойчивый незнакомец, убеждающий отдать пакет, группа громил в переулке, наёмный вор, подкупленная стража... Что стоит на кону? На усмотрение мастера." },
      { from: 78, to: 78, text: "Когда будете ложиться спать, не забудьте проверить, ясное ли сегодня небо. Если да, совершите проверку Интеллекта (Сл 12). В случае неудачи вы имеете риск провести ночь... Не так, как обычно. Начиная с этой ночи, вы страдаете лунатизмом, обнаруживая себя в самых неожиданных местах. Насколько ваше пробуждение будет безопасным определяет мастер через проверку 1к20. Проснувшись, однако, совершите бросок любого куба: если выпадает чётное число - в карманах вашей одежды или в сжатом кулаке вы обнаруживаете щепотку пыльцы пикси, если выпадает нечётное - споры волчьего табака. Лунатизм можно излечить, совершив молебен и подношение лунному божеству." },
      { from: 79, to: 79, text: "Вы обнаруживаете в траве замечательную находку: потёртое кольцо с тёмным камнем, которое на поверку оказывается волшебным! Изучение говорит вам, что вы можете раз в день в бою приказать кольцу придать вашей руке силы и точности, что увеличит любую вашу Атаку на +3... Однако, только успешная проверка Магии или Истории со Сл 20 даст вам возможность распознать сосредоточие дикой магии внутри камня или затёртую руну на внутренней стороне, обозначающую дикую магию в чертежах волшебников. В ином случае, первый же приказ вызовет эффект согласно таблице дикой магии!" },
      { from: 80, to: 80, text: "Вода из последнего источника (или кружка \"особого эля\" в последнем трактире) имела необычный привкус. Совершите проверку Телосложения (Сл 18). В случае провала, вы чувствуете уверенность в том, что ваши мышцы наливаются необычайной мощью: получите состояние Очарованный на ближайшие 1к4 дней, на это время Сила становится вашей основной характеристикой ко всем проверкам Атак, включая заклинания. Если вы не снимаете это состояние магией или божественным вмешательством, в последний день недуга вы чувствуете заметное улучшение: получите +1 к спасброскам и проверкам Силы на ближайшие 1к4 дней." },
      { from: 81, to: 81, text: "Недалеко от города, у места, которое не обойти (вроде парома, моста, узкой теснины в горах) партия натыкается на любопытную встречу. В сопровождении двух скучающих наёмников, носящих отличительные знаки некоего благородного дома, туда-сюда нетерпеливо прохаживается юнец в дорожном костюме. Завидев вас, встречные испытывают оживление. Юнец указывает пальцем именно на вас, и отмечает, что с вашей стороны довольно учтиво явится на место дуэли пораньше. Любых ваших спутников он принимает за сопровождение и секундантов, и, требуя не откладывать дело в долгий ящик, просит одного из наёмников озвучить принятый церемониал, чтобы он мог получить сатисфакцию \"за вчерашний инцидент в таверне\". Вам наверняка любопытно узнать, что же именно стряслось? Вчера вы (юнец озвучивает несколько конкретных ваших отличительных особенностей, которые он хорошо запомнил \"несмотря на некоторую неумеренность в возлияниях по случаю удачной охоты\") имели наглость оскорбить его, а когда он потребовал извинений, также присовокупили к оскорблению отца, мать и бабушку юнца. Разумеется, оставить это просто так он не имеет никакой возможности и жаждет проучить вас. Переубедить его, конечно, можно, если у вас будет достаточно Харизмы (Сл 18)... В ином случае, юноша принимает фехтовальную стойку. Его слова - не пустой звук: он отменно владеет своей рапирой (+7 к Атаке) и дагой (+7 к Атаке), не испытывая помехи от обращения с двумя оружиями. Сама его рапира имеет волнообразное лезвие (урон +2), раны от которой сложны и излечиваются с помехой. Если дворянчик первым опускает значение ваших хитов до половины, он предлагает вам признать поражение (и, в случае вашего согласия, он требует, по законам чести, ваше оружие или выкуп за него), либо продолжая бой, стараясь лишить вас чувств (т.е. не станет вас добивать). В обратном случае, он признаёт вашу победу. Если вы останавливаетесь и принимаете его поражение, он с скорбным видом передаёт вам свою искусно сделанную рапиру. Если же вы продолжаете бой, в борьбу вмешиваются два его секунданта. Каким бы ни был исход вашей схватки (или, если вам удалось отговорить юнца - сразу после того, как он признает ошибку), оттуда, откуда вы прибыли, показывается похожий на вас субъект, оснащённый подобно дворянину в сопровождении пяти своих вооружённых слуг. Вот только он не намерен драться по законам чести..." },
      { from: 82, to: 82, text: "Вода из последнего источника (или кружка \"особого эля\" в последнем трактире) имела необычный привкус. Совершите проверку Телосложения (Сл 18). В случае провала, вы чувствуете уверенность в том, что ваши рефлексы чудесным образом обострились: получите состояние Очарованный на ближайшие 1к4 дней, на это время Ловкость становится вашей основной характеристикой ко всем проверкам Атак, включая заклинания. Если вы не снимаете это состояние магией или божественным вмешательством, в последний день недуга вы чувствуете заметное улучшение: получите +1 к спасброскам и проверкам Ловкости на ближайшие 1к4 дней." },
      { from: 83, to: 83, text: "Вы обнаруживаете в траве замечательную находку: потёртое кольцо с насыщенным алым камнем (по которому проходит малая трещинка), которое на поверку оказывается волшебным! Изучение говорит вам, что вы можете раз в день в бою приказать кольцу атаковать противника Огненной стрелой [Fire bolt]!.. При каждом использовании делайте проверку броском 1к20. При результате больше 10 ничего не происходит; при результате меньше 10 на камне можно обнаружить одну трещинку; результат 20 убирает одну трещинку; а результат 3 и менее добавляет сразу две трещинки и вызывает поломку кольца. При поломке камень звонко трескается, высвобождая сноп малых огненных стрел, число которых равно числу трещин на камне. Все, кто находится в радиусе 25 футов от носителя кольца, включая самого носителя кольца, должны совершить спасбросок Ловкости (Сл 16), чтобы избежать атаки. Носитель кольца совершает проверку с помехой и более высокой сложностью (Сл 18). Число высвободившихся огненных стрел распределяется между провалившими спасбросок: каждая наносит 1к4 огненного урона." },
      { from: 84, to: 84, text: "Сегодня вам явно нездоровится. Вы чувствуете общую слабость и ломоту в мышцах, отчего всякое лишнее мышечное напряжение вызывает резкую боль. Совершите спасбросок Телосложения (Сл 18): в случае успеха, ваши страдания окончатся к вечеру, иначе недуг затянется на 1к4 дней. В любом случае, он сопровождается штрафом -4 к вашей характеристике Силы. Если вам не посчастливилось отделаться от болезни одним днём или снять её симптомы любым другим лечением, на следующий день после естественного выздоровления вы получаете приятный временный бонус +1 ко всем проверкам, основанным на Силе!" },
      { from: 85, to: 85, text: "И как только никто не заметил этот небольшой кошель? Внутри находится 12 золотых монет!.. И все они - мимики. Чтобы увернуться от их атаки, пройдите спасбросок Ловкости (Сл 16). Каждая монета имеет 1 hp и штраф -2 к Атаке, наносит 1 колющего урона в случае успеха." },
      { from: 86, to: 86, text: "Вам кажется, будто кто-то идёт прямо по вашим следам. Буквально спиной чувствуете его присутствие. Иногда даже слышите его шёпот или видите постороннее движение на периферии зрения. Несмотря на это, никакие проверки поиска не дают результата, кроме заклинаний и проверок с магическим эффектом Обнаружения существ: вас преследует неясная сущность, аберрация с Плана Теней, которая питается вашим беспокойством. Изгнание или Защита от аберрации смогут избавить вас от напасти, но до тех пор вы претерпеваете от его присутствия -10 к проверкам Внимательности и Восприятия." },
      { from: 87, to: 87, text: "Когда в следующий раз вы будете пить покупной напиток, совершите проверку Внимательности, каким бы высоким ни было значение вашей пассивной проверки (Сл 12). В случае успеха вы замечаете плавающую на поверхности осу. В случае, если сообщить об этом тому, кто дал вам этот напиток, вы получите более дорогой. В случае неудачи вы получите 1 урона, состояние Отравленный и вскоре начнёте задыхаться от отёка гортани. Только магическое лечение может прекратить все эти эффекты. Что за странное совпадение? Очень просто: кто-то вас проклял." },
      { from: 88, to: 88, text: "Вода из последнего источника (или кружка \"особого эля\" в последнем трактире) имела необычный привкус. Совершите проверку Телосложения (Сл 18). В случае провала, вы чувствуете уверенность в том, что ваша природная харизма достойна применения: получите состояние Очарованный на ближайшие 1к4 дней, на это время Харизма становится вашей основной характеристикой ко всем проверкам Атак, включая заклинания. Если вы не снимаете это состояние магией или божественным вмешательством, в последний день недуга вы чувствуете заметное улучшение: получите +1 к спасброскам и проверкам Харизмы на ближайшие 1к4 дней." },
      { from: 89, to: 89, text: "Дорогу вам преграждает бревно. Позади него стоят кобольды, около десятка. Навстречу вам выходит кобольдшаман и говорит, что бог Куртулмак указал ему это место как судьбоносное: Жребий говорит, что тут должна произойти дуэль с чемпионом кобольдов против того, кого выберут кости. Если вы победите, получите все \"блестяшки\", что есть у кобольдов, если нет - отдадите все \"блестяшки\", что есть у вас. Тут же выходит и чемпион: с виду - обычный кобольд, покрытый грязным красным плащом с капюшоном, скрестивший руки на груди, благодаря чему видно, что за поясом у него - вилка и ложка: видимо, это его оружие. Жребий шамана указывает на вас, и бой начинается. Чемпион сбрасывает накидку и тут же оказывается, что это не простой кобольд, а урд: у него есть крылья и он летает. Кроме того, он более ловок, чем обычный кобольд (Лов. 18), силён (Сил. 10) и живуч (28 hp). Кроме того, он умеет сражаться двумя руками, совершая по две Атаки за ход своим странным оружием: вилка наносит 1к4 колющего урона, ложка - 1к4 дробящего. Что примечательно: оба оружия всегда совершают критический успех! Вы или ваши спутники могут попробовать присмотреться к маленьким тёмным столовым приборам (Внимательность Сл 18) и постараться вспомнить, что может обладать такими свойствами (История Сл 16): непонятно, при каких обстоятельствах они оказались у кобольдов, но это адамантиновые вилка и ложка!.. В случае победы над Чемпионом Куртулмака вы получаете свободный проход и казну кобольдов: все 12 золотых монет и один маленький топаз (100 зм)!" },
      { from: 90, to: 90, text: "Вода из последнего источника (или кружка \"особого эля\" в последнем трактире) имела необычный привкус. Совершите проверку Телосложения (Сл 18). В случае провала, вы чувствуете уверенность в том, что ваш жизненный опыт и связь с окружающим миром должны вести вас впредь: получите состояние Очарованный на ближайшие 1к4 дней, на это время Мудрость становится вашей основной характеристикой ко всем проверкам Атак, включая заклинания. Если вы не снимаете это состояние магией или божественным вмешательством, в последний день недуга вы чувствуете заметное улучшение: получите +1 к спасброскам и проверкам Мудрости на ближайшие 1к4 дней." },
      { from: 91, to: 91, text: "Сегодня вам повезло: ваше зло останется безнаказанным." },
      { from: 92, to: 92, text: "Следующую ночь вам плохо спится: во сне вам чудится, словно кто-то следит за вами. Проснувшись, вы оглядываетесь вокруг. Словно бы ничего необычного, но невдалеке от вашего лагеря (или на улице, видимой через окно) вы замечаете странную человеческую фигуру, которая, как вам кажется, стоит и следит за вами. Если вы попытаетесь подойти к ней, в какой-то момент она просто исчезнет, пока вы моргали. Если вы разбудите остальных, на месте фигуры они не увидят никого. То же самое повторяется каждую ночь, и каждый раз вы чувствуете всё возрастающую угрозу. На шестую ночь вы просыпаетесь, но фигуры нигде нет. Кажется, что морок отступил. Однако, на седьмую ночь, когда вы просыпаетесь от того же сна перед вашей постелью стоит Бодак." },
      { from: 93, to: 93, text: "Вас терзает странное чувство. Такое ощущение, словно ваша магическая фокусировка или ваше оружие, которым вы пользовались всё это время и которое служило вам верой и правдой... Не слушается вас. То ли рукоять под другую руку, то ли вес изменился - вы никак не можете понять, в чём именно дело. Так или иначе, пока вы пользуетесь этим предметом снаряжения, вы нервничаете и получаете за это штраф -2 к вашим проверкам Атак на протяжении 1к4 дней." },
      { from: 94, to: 94, text: "Когда вы заговариваете с ремесленником или торговцем, которого видите впервые, тот с готовностью сообщает вам, что заказ выполнен: он смог изготовить / раздобыть необходимую вам вещь! Ранее ему оплатили труды и описали, как будет выглядеть тот, кто за ним придет. Проверки Проницательности показывают, что хозяин лавки твёрдо уверен в сказанном. Если игрок всё же возьмет добытый предмет, это окажется некий элемент доспеха или одежды, вроде кирасы или перчаток, искусно выполненный, без признаков магии. Пассивная Внимательность 18 покажет, что предмет источает еле уловимый сладковатый запах. В ином случае, тот, кто наденет на себя этот предмет, должен совершить спасбросок Телосложения на следующий день после ношения (Сл. 18), иначе получает статус Отравлен: вещь была изнутри пропитана медленно действующим ядом! Вернувшись к лавочнику, вы не добьётесь от него ответов: он сам искренне удивлён инциденту. Также он может рассказать о подмастерье, который нанялся к нему недавно, но пропал после того, как авантюристы получили предмет..." },
      { from: 95, to: 95, text: "Сегодня вам явно нездоровится. Вы чувствуете невероятную слабость, а ваше дыхание страшно затруднено. Совершите спасбросок Телосложения (Сл 18): в случае успеха, ваши страдания окончатся к вечеру, иначе недуг затянется на 1к4 дней. В любом случае, он сопровождается штрафом -4 к вашей характеристике Телосложения, ваши максимальные хиты временно снижаются на максимальное значение 1 вашей кости здоровья, а скорость снижается на 20 футов. Если вам не посчастливилось отделаться от болезни одним днём или снять её симптомы любым другим лечением, на следующий день после естественного выздоровления вы получаете приятный временный бонус +1 ко всем проверкам, основанным на Телосложении и +5 футов к Скорости!" },
      { from: 96, to: 96, text: "Сегодня вам явно нездоровится. Вы чувствуете общую слабость и опоясывающую головную боль, отчего сконцентрироваться на чём-либо становится просто невозможно. Совершите спасбросок Телосложения (Сл 18): в случае успеха, ваши страдания окончатся к вечеру, иначе недуг затянется на 1к4 дней. В любом случае, он сопровождается штрафом -2 к вашим характеристикам Интеллекта и Мудрости. Если вам не посчастливилось отделаться от болезни одним днём или снять её симптомы любым другим лечением, на следующий день после естественного выздоровления вы получаете приятный временный бонус +1 ко всем проверкам, основанным на Интеллекте или Мудрости!" },
      { from: 97, to: 97, text: "Сегодня вам явно нездоровится. Вы чувствуете общую слабость, голос хрипит, ваши глаза слезятся, а на вашем лице, груди и руках появляется отёк и яркая красная сыпь. Совершите спасбросок Телосложения (Сл 18): в случае успеха, ваши страдания окончатся к вечеру, иначе недуг затянется на 1к4 дней. В любом случае, он сопровождается штрафом -4 к вашей характеристике Харизмы. Если вам не посчастливилось отделаться от болезни одним днём или снять её симптомы любым другим лечением, на следующий день после естественного выздоровления вы получаете приятный временный бонус +1 ко всем проверкам, основанным на Харизме!" },
      { from: 98, to: 98, text: "На улице вы сталкиваетесь плечами с неким неприметным человеком. Тот торопливо извиняется и идёт дальше. Осмотрев свои вещи, вы понимаете, что кошель и прочее на месте, но за поясом / в кармане вы находите письмо без обратного адреса. Почерк и штиль письма говорят высоком положении отправителя. Содержание же повествует историю от лица любовника с разбитым сердцем, которое не в силах далее терпеть безответность: «Раз уж вы мне не достались, мы с вами не достанемся никому». Через пару дней на вас будет совершено покушение. Если вы попытаетесь пройти по следу подосланного убийцы, чтобы узнать личность нанимателя, найдёте лишь смерть: отправитель был похоронен за день до ваших поисков после самоубийства." },
      { from: 99, to: 99, text: "Перебросьте кости. Нужно выбрать что-то особенное!" },
      { from: 100, to: 100, text: "Согласно статистике некоторых астрологов, каждые 7 лет на кого-нибудь падает метеорит массой около полуфунта или больше. Сегодня это вы. Бросьте 1к4: это масса упавшего на вас метеорита. Бросьте количество к4, равное выпавшему числу: это полученный вами урон. Можете успокаивать себя тем фактом, что у вас теперь есть кусок метеоритного железа соответствующей массы." },
    ],
  },
];
